#!/usr/bin/env python3
import argparse, json, os, pathlib, sys
from datetime import datetime, timezone


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Find newest file(s) matching a glob by modification time"
    )
    parser.add_argument("--dir", required=True, help="Directory to search")
    parser.add_argument("--glob", required=True, help="Glob pattern (e.g. *.yaml)")
    parser.add_argument("--limit", type=int, default=1, help="Number of newest files to return")
    args = parser.parse_args()

    root = pathlib.Path(args.dir)
    if not root.is_dir():
        print(f"Error: {args.dir} is not a directory or does not exist", file=sys.stderr)
        sys.exit(1)

    matches = []
    for p in root.glob(args.glob):
        if not p.is_file():
            continue
        stat = p.stat()
        matches.append({
            "path": str(p.relative_to(root)),
            "mtime": datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc).isoformat(),
            "size": stat.st_size,
        })

    if not matches:
        print(f"No files matching '{args.glob}' in {args.dir}", file=sys.stderr)
        sys.exit(1)

    matches.sort(key=lambda x: x["mtime"], reverse=True)
    for entry in matches[: args.limit]:
        print(json.dumps(entry))


if __name__ == "__main__":
    main()

